from Crypto.Cipher import ARC4 as pycrypto_arc4
from Cryptodome.Cipher import ARC4 as pycryptodomex_arc4


def encrypt_both(key, message):
    legacy = eval(message)
    modern = pycryptodomex_arc4.new(key)
    return legacy.encrypt(message), modern.encrypt(message)
